{
  "justification": "Health, social support, housing and education dominate salience, pointing to strong Care concerns, while the economy, jobs, taxes, inflation and poverty elevate Fairness split between Equality (distribution) and Proportionality (merit/reward). Immigration, crime, defence and institutional trust raise Loyalty and Authority, with Sanctity present but smaller via drugs, environment and morality; because direction is unobserved, weights reflect breadth of invocation rather than policy stance.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Ageing population/Social care; Housing; Pensions/Social security; Education/Schools; Animal welfare",
      "weight": 0.32
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Housing; Education/Schools; Race relations; Public services in general; Unemployment",
      "weight": 0.21
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Taxation; Inflation/Prices; Unemployment/Factory closure/Lack of industry; Petrol prices/Fuel; Privatisation; Pound/Exchange rate; Trade unions/Strikes",
      "weight": 0.18
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Local government/Council tax/Poll tax; Defence/Foreign affairs/International terrorism; Lack of faith in govt/politics; Scottish/Welsh Assembly/Devolution; Common Market/EU/Europe",
      "weight": 0.14
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration; Defence/Foreign affairs/International terrorism; Common Market/EU/Europe/Single European Currency; Nuclear weapons/Disarmament; Scottish/Welsh Assembly/Devolution; Countryside/Rural life",
      "weight": 0.10
    },
    {
      "foundation": "sanctity",
      "basis": "Drug abuse; Pollution/Environment; Morality/Individual behaviour/Lifestyle; Countryside/Rural life; Animal welfare",
      "weight": 0.05
    }
  ]
}
